-- 192 · 站点结构类后台模板文案词条（审计 I18N-001 组E）。
--
-- 覆盖 internal/templates/admin/ 下 9 个模板：site_slots / theme / theme_settings /
-- pages / page_translations / blocks / navigations / navigation_translations / menus。
-- 模板侧改成 {{ .["t"]("admin.<模块>.<语义>", "中文兜底") }}（range 内先 {{tr := .["t"]}} 再 tr(...)），
-- 真文案落在本表：响应层 pkg/i18n.Translate 按请求语言查表，缺 key 时回落到模板内的中文原文。
--
-- 分片说明：这些页面里有若干内联 <strong>/<b> 的长说明句。词条一律保持**纯文本**
-- （与既有全量词条一致，输出仍走 Jet 默认 HTML 转义，不引入 raw），
-- 因此按标签边界拆成若干语义完整的片段，由 HTML 标签拼接回原句。
-- 主题说明里的 :root / --sky-* 变量名、页面路径、data 属性值都不是文案，保持原样。
--
-- 幂等：ON CONFLICT (item_key, lang) DO NOTHING —— seed 是默认值来源，后台是真相来源。

INSERT INTO sys_i18n (item_key, lang, item_value, http_code, category, remark, status, create_time, update_time)
