    ('admin.site_slots.intro1.strong', 'en-US', 'page that plays the checkout role', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.mid', 'zh-CN', '」这类事实固定下来：购物车片段的「去结算」、访客订单列表的「查看订单」、登录页与注册页的互跳，都来这里取路径。', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.mid', 'en-US', ': the cart fragment link, the guest order list link, and the login and signup cross links all read their paths from here.', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.strong2', 'zh-CN', '改页面的 URL 不影响这里的绑定', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.strong2', 'en-US', 'Changing a page URL does not break the binding here', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.tail', 'zh-CN', ' —— 槽位绑的是页面本身，页面换了访问路径，指向它的链接自动跟着走。', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro1.tail', 'en-US', ' — a slot binds the page itself, so links pointing at it follow along when the path changes.', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
