    ('admin.site_slots.intro2.strong', 'en-US', 'one page can hold several slots at once', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro2.mid', 'zh-CN', '（「个人中心页同时是订单页」是常见用法）。', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro2.mid', 'en-US', ' (an account page that is also the orders page is a common pattern). ', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
