    ('admin.site_slots.intro2.tail', 'zh-CN', ' —— 这个站没有博客、没有结算页，就让它空着。', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
    ('admin.site_slots.intro2.tail', 'en-US', ' — if this site has no blog and no checkout page, leave it empty.', 200, 'admin', 'admin/site_slots.html', 1, now(), now()),
