    ('admin.blocks.notes_reuse_global_tail', 'en-US', ' means the page stores a reference, so editing once updates every referencing page (headers, announcement bars, trust badges); ', 200, 'admin', 'admin/blocks.html', 1, now(), now()),
    ('admin.blocks.notes_reuse_template', 'zh-CN', '一次性复制', 200, 'admin', 'admin/blocks.html', 1, now(), now()),
