    ('admin.blocks.notes_reuse_template_tail', 'zh-CN', '＝插入时复制完整结构，此后与源块互不影响（商品卡/表单/弹窗）。被引用的全局块删除前须先解除引用。', 200, 'admin', 'admin/blocks.html', 1, now(), now()),
